  int Z;
  int i, j, k; 
    for(i = 0; i < size; i++)
    Y = Y + E[i];
  for(i = 0; i < size; i++)
    for(j = i; j < size; j++)
    {
       Z = 0;
       for(k = i; k <= j; k++)
           Z= Z + E[k];
       if (Z > Y)
            Y = Z;
   }
return Y;
}</code></pre>
